import cocotb
from cocotb.clock import Clock
from cocotb.triggers import ClockCycles

import cocotb
from cocotb.clock import Clock
from cocotb.triggers import ClockCycles

@cocotb.test()
async def rom_builtin(dut):
    dut._log.info("Start")

    F = 1 # clock frequency multiplier
    
    # Set the clock period to 40 ns (25 MHz ~ VGA pixel clock)
    clock = Clock(dut.clk, 40//F, units="ns")
    cocotb.start_soon(clock.start())

    # Reset
    dut._log.info("Reset")
    dut.ena.value = 1
    dut.ui_in.value = 0b1_0000 # 0b1_xxxx for built-in ROMs
    dut.uio_in.value = 0
    dut.rst_n.value = 1
    await ClockCycles(dut.clk, 2*F)
    dut.rst_n.value = 0
    await ClockCycles(dut.clk, 10*F)
    dut.rst_n.value = 1
    dut.ui_in.value = 0

    dut._log.info("Start")
    await ClockCycles(dut.clk, 16)
    assert(dut.PC.value.integer == 0xfffd)
    await ClockCycles(dut.clk, 16)
    assert(dut.PC.value.integer == 0xfffd)
    await ClockCycles(dut.clk, 16)
    assert(dut.PC.value.integer == 0xfffd)
