@cocotb.test()
async def rom_1(dut):
    dut._log.info("Start")

    F = 1 # clock frequency multiplier
    
    # Set the clock period to 40 ns (25 MHz ~ VGA pixel clock)
    clock = Clock(dut.clk, 40//F, units="ns")
    cocotb.start_soon(clock.start())

    # Reset
